Internal line format:  <64 board chars, '1' = empty, a8..h8,a7..h1> <castle> <ep>\n
"""

import json

E = "1"  # empty-square char
rules = []


def name(i):
    return "abcdefgh"[i % 8] + str(8 - i // 8)


def fr(i):
    return i // 8, i % 8


def on(r, f):
    return 0 <= r < 8 and 0 <= f < 8


def sq(r, f):
    return r * 8 + f


def board_constraint(cons):
    """Regex (from line start) checking given {index: charclass} constraints."""
    out, pos = [], 0
    for i in sorted(cons):
        if i > pos:
            out.append(".{%d}" % (i - pos))
        out.append(cons[i])
        pos = i + 1
    return "".join(out)


def gen_move(cons, changes, castle_pat=r"(\S+)", src_ep=r"\S+", new_ep="-"):
    """Rule: if source line satisfies cons, insert new line with changes applied."""
    special = sorted(set(cons) | set(changes))
    pat, rep, pos, g = [r"\A"], [r"\g<0>"], 0, 0
    for i in special:
        if i > pos:
            g += 1
            pat.append("(.{%d})" % (i - pos))
            rep.append(r"\g<%d>" % g)
        if i in changes:
            pat.append(cons.get(i, "."))
            rep.append(changes[i])
        else:
            g += 1
            pat.append("(%s)" % cons[i])
            rep.append(r"\g<%d>" % g)
        pos = i + 1
    rep = [r'\g<%d>' % gid[x[1]] if isinstance(x, tuple) else x for x in rep]
    if pos < 64:
        g += 1
        pat.append("(.{%d})" % (64 - pos))
        rep.append(r"\g<%d>" % g)
    g += 1
    pat.append(" %s %s\n" % (castle_pat, src_ep))
    rep.append(r" \g<%d> %s" % (g, new_ep) + "\n")
    rules.append(["".join(pat), "".join(rep)])


TGT = "[1qrbnp]"  # empty or capturable black piece
BLK = "[qrbnp]"

# ---------------- 1. preprocessing ----------------
for d in range(8, 1, -1):
    rules.append([r"%d(?=[^ ]* w )" % d, E * d])
rules.append([r"/", ""])
rules.append([r" w (\S+) (\S+) \S+ \S+$", r" \1 \2" + "\n"])

# ---------------- 2. move generation ----------------
KN = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
KG = [(a, b) for a in (-1, 0, 1) for b in (-1, 0, 1) if (a, b) != (0, 0)]
ORTH = [(1, 0), (-1, 0), (0, 1), (0, -1)]
DIAG = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

for i in range(64):
