    # knight / king steps
    for piece, offs in (("N", KN), ("K", KG)):
        for dr, df in offs:
            if on(r + dr, f + df):
                j = sq(r + dr, f + df)
                gen_move({i: piece, j: TGT}, {i: E, j: piece})
    # sliders
    for piece, dirs in (("R", ORTH), ("B", DIAG), ("Q", ORTH + DIAG)):
        for dr, df in dirs:
            path = []
            rr, ff = r + dr, f + df
            while on(rr, ff):
                j = sq(rr, ff)
                cons = {i: piece, j: TGT}
                for p in path:
                    cons[p] = E
                gen_move(cons, {i: E, j: ('ref', i)})
                path.append(j)
                rr += dr
                ff += df
    # pawns
    if 1 <= r <= 6:
        j = i - 8
        out = "Q" if r == 1 else "P"
        gen_move({i: "P", j: E}, {i: E, j: out})
        if r == 6:
            gen_move({i: "P", j: E, i - 16: E}, {i: E, i - 16: "P"}, new_ep=name(j))
