gen_move(
    {60: "K", 61: E, 62: E, 63: "R"},
    {60: "K", 61: "K", 62: "K", 63: E},
    castle_pat=r"(\S*K\S*)",
)
gen_move(
    {60: "K", 59: E, 58: E, 57: E, 56: "R"},
    {56: E, 58: "K", 59: "K", 60: "K"},
    castle_pat=r"(\S*Q\S*)",
)

# ---------------- 3. drop source line ----------------
rules.append([r"\A.*\n", ""])

