for s in range(64):
    r, f = fr(s)
    alts = []
    for dr, df in KN:
        if on(r + dr, f + df):
            alts.append(board_constraint({sq(r + dr, f + df): "n"}))
    for dr, df in KG:
        if on(r + dr, f + df):
            alts.append(board_constraint({sq(r + dr, f + df): "k"}))
    for df in (-1, 1):
        if on(r - 1, f + df):
            alts.append(board_constraint({sq(r - 1, f + df): "p"}))
