                for p in path:
                    cons[p] = E
                alts.append(board_constraint(cons))
                path.append(j)
                rr += dr
                ff += df
    pat = (
        r"(?m)^(?=.{%d}K)(?=%s).*\n" % (s, "|".join(alts))
        if s
        else r"(?m)^(?=K)(?=%s).*\n" % "|".join(alts)
    )
    rules.append([pat, ""])

# ---------------- 5. finish castling ----------------
rules.append([r"(?m)^(.{60})KKK", r"\g<1>1RK"])
rules.append([r"(?m)^(.{58})KKK", r"\g<1>KR1"])

# ---------------- 6. castling rights ----------------
rules.append([r"(?m)^((?!.{60}K).{64} [^ KQ]*)[KQ]", r"\1"])
rules.append([r"(?m)^((?!.{60}K).{64} [^ KQ]*)[KQ]", r"\1"])
rules.append([r"(?m)^((?!.{63}R).{64} [^ K]*)K", r"\1"])
rules.append([r"(?m)^((?!.{56}R).{64} [^ Q]*)Q", r"\1"])
rules.append([r"(?m)^((?!.{7}r).{64} [^ k]*)k", r"\1"])
rules.append([r"(?m)^((?!r).{64} [^ q]*)q", r"\1"])
rules.append([r"(?m)^(.{64})  ", r"\1 - "])

# ---------------- 7. output formatting ----------------
rules.append(
    [
        r"(?m)^" + "(.{8})" * 8 + r" (\S+) (\S+)$",
        "/".join(r"\g<%d>" % k for k in range(1, 9)) + r" b \g<9> \g<10> 0 0",
    ]
)
for d in range(8, 1, -1):
    rules.append([E * d, str(d)])
rules.append([r"\n\Z", ""])

json.dump(rules, open("re.json", "w"))
print(len(rules), "rules")

